A={
"1277031963340647":("Dor + tutorial","Pergunta de dor (acordar cedo pra otimizar) e já entrega o passo a passo na tela.","Tutorial que vende: o anúncio ensina de verdade usando a ferramenta. 9 variações e 2 anos rodando.","Gravar 'deixa a IA otimizar sua campanha' mostrando o Claude fazendo, com CTA pra mentoria."),
"988346492250342":("Imagine + objeção","'Imagine acordar com dezenas de mensagens no WhatsApp', depois quebra a objeção 'bom demais pra ser verdade'.","Desejo concreto e visual em 3 segundos. Roda há 3 anos.","Abrir com a cena do resultado: 'imagina acordar com vendas no Hotmart sem ter gravado nada hoje'."),
"246500875009198":("Objeto curioso","Mostra uma maleta de pedais e promete revelar no fim a relação com seus clientes.","Loop aberto: só fecha no final, prende até o CTA. 3 anos rodando.","Usar um objeto do seu setup (luz, teclado) como metáfora de funil."),
"424355000153288":("Confusão + guia","'Tá uma confusão na sua cabeça, um monte de guru...' e se coloca como direção única.","Nomeia o caos que o iniciante sente e oferece um caminho.","Versão IA: 'todo dia sai uma ferramenta nova e você não sabe por onde começar'."),
"1284781858883976":("Confusão + guia","Mesma copy do anterior em outro formato (quadrado).","Mesma copy reaproveitada em vários formatos: prova de criativo vencedor.","Ao achar um vencedor, exportar 9:16, 1:1 e 4:5."),
"1397544655796296":("Pergunta de dinheiro","'Quanto ganha um gestor de tráfego?' e responde com números (10 a 15 clientes de R$500 a 1.500).","Curiosidade financeira e números concretos. 14 variações pra aula gratuita.","'Quanto dá pra cobrar pra montar um agente de IA pra uma empresa?' com números."),
"2839929833024038":("Notícia/fofoca","Comenta uma notícia do mercado (Meta e Manus) como fofoca, depois conecta ao produto.","Newsjacking: o anúncio parece conteúdo e pega carona no assunto do dia.","Toda notícia grande de IA vira um criativo em até 24h."),
"1579637583706656":("Resultado + replicável","'Meu Instagram bate 1,4 milhão de views por dia, vou te mostrar o que fiz e você consegue replicar'.","Número absurdo, promessa de bastidor e 'você consegue também'.","Mostrar os números da sua máquina de conteúdo e oferecer replicar."),
"4315313032055281":("Teoria com nome","'A Matrix da Classe Média, já ouviu essa teoria?'","Uma ideia com nome próprio vira identidade e o espectador quer entender.","Batizar seu método (ex: 'o Cérebro') e abrir explicando a teoria."),
"1162176479472850":("História longa","VSL de 10 min que abre com cena de madrugada ('23h47 de uma sexta').","Storytelling de dor do gestor sobrecarregado; vídeo longo pra público quente.","VSL da mentoria: sua história antes da IA."),
"2344157225987755":("Notícia que mata profissão","'A Meta acabou de enterrar a profissão do gestor de tráfego' (MCP e CLI do Facebook Ads).","Medo e novidade juntos; a demo na tela prova a promessa.","O seu nicho exato: tráfego com IA. Modelar já."),
"1890655135253005":("Didático em 3 peças","'No Claude Code existem 3 peças: Agents, Skills e MCP'; explica cada uma numa frase.","Ensina algo útil em 40s e chama pra imersão gratuita. 5 variações.","Criativo-aula pra sua aula gratuita de Claude."),
"1229055652490083":("Erro do iniciante","'O maior erro de quem começa a estudar IA é não saber que existem 4 caminhos'.","Erro + lista numerada prende até o último item. Quase 1 ano rodando.","'3 jeitos de usar IA no tráfego, e só um dá dinheiro'."),
"1699085797908117":("Humor com meme","'Claudinho tá sendo explorado' (só música e meme, sem fala).","Meme leve funciona como topo de funil barato.","Meme do Claude trabalhando enquanto você dorme."),
"4584765268517687":("Lançamento direto","'Acabou de lançar a trilha Dominando o Ecossistema do Claude'.","Anúncio direto pra quem já procura Claude.","Pouco a copiar além do posicionamento."),
"3663274000490649":("Ranking top 5","'Top 5 funções do Claude, bora?' em formato de ranking.","Ranking cria expectativa do número 1.","'Top 5 skills de Claude pra gestor de tráfego'."),
"1790789798714514":("Condição especial","'Se você perdeu minha condição especial, essa pode ser a última do ano'.","Escassez e prova social de arrependimento.","Black Friday da mentoria."),
"949130958259186":("Comparação de preço","'O GPT custa 100, o Claude 120, o Gemini 100, mas você não precisa gastar nada disso'.","Âncora de preço nos 3 primeiros segundos.","Ancorar o preço da mentoria contra o custo de contratar uma agência."),
"1667686344991035":("Mata-mata","Joel Jota em eliminatória 'GPT ou Claude?' até a final.","Formato de torneio prende até o vencedor; autoridade conhecida.","Fazer o mata-mata das ferramentas de tráfego com IA."),
"982366638173147":("Caso de aluna","'Minha mentorada investiu R$650 e voltou 10 mil em 2 meses' sem gestor e sem experiência.","Prova específica com números e quebra a objeção da experiência.","Usar caso de aluno com números reais."),
"1673266880671689":("Desafio 30 dias","'30 dias, 30 ideias de low ticket' com o pai querendo viver do digital.","Série e história de família geram empatia.","Série '30 dias de IA no tráfego'."),
"2074290526501614":("Bastidor tático","'Esse criativo me deu 250 vendas, faço só isso: coloco o print do Twitter em cima'.","Dica tática que dá pra copiar na hora.","'Esse prompt me deu X vendas' mostrando o prompt."),
"4239391002993278":("Pilares numerados","'Vamos vender 100 mil/mês com low ticket; o primeiro pilar é...'.","Promessa grande e lista de pilares.","'Os 3 pilares da minha operação com IA'."),
"1819190359067289":("Depoimento em print","O aluno grava a tela mostrando faturamento, gasto e ROAS do dia.","Prova crua no celular, parece real.","Pedir aos alunos vídeos de tela com resultado."),
"947157811220026":("Pergunta estranha","'Paz, irmão, você entraria no carro?'","Pergunta sem contexto quebra o padrão do scroll.","Abrir com uma pergunta absurda ligada à IA."),
"1946469459236186":("Humor técnico","Vídeo de humor diagnosticando métricas (CPC alto, CTR baixo...).","Público de tráfego se identifica com o jargão. 10 meses rodando.","Esquete 'o Claude diagnosticando sua campanha'."),
"1664433521491698":("Número + transformação","'80 opções saudáveis pra sair do pão com café'.","Número grande e troca simples; mostra o produto folheando.","'87 prompts de tráfego prontos'."),
"1535272957646251":("Antes e depois","'Olha como minha aluna cantava... agora olha depois do método'.","Antes e depois audível é prova irrefutável. 1 ano e 2 meses rodando.","Antes e depois de um criativo ou de uma conta de anúncios."),
"2160940891500435":("Autoridade de recorde","'Sou o primeiro brasileiro a falar inglês em 8 semanas'.","Claim único com nome próprio. 9 variações.","'Montei uma máquina que posta X vídeos por dia sozinha'."),
"1407719990900998":("Descoberta pessoal","'Queria ter descoberto isso antes', depois mostra o material folheando.","Tom de recomendação de amigo, estilo UGC.","Criativo UGC mostrando o Cérebro funcionando."),
"27996304793378437":("Aposta de 7 dias","'Me dá 7 dias e esse homem vai te olhar diferente. Quer apostar?'","Promessa com prazo e desafio direto. De R$497 por R$49,90.","'Me dá 7 dias e você vai rodar campanha com IA'."),
"911051598194719":("Contra-intuitivo","'Ninar acalma, mas não ensina o bebê a dormir'.","Derruba uma crença comum logo de cara.","'Subir o orçamento não escala sua campanha'."),
}
